insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('disenando-una-propuesta-para-fortalecer-la-participacion-colecti','sociedad',array['derecho']::text[],'Diseñando una propuesta para fortalecer la participación colectiva con un mecanismo participativo','Diseña un mecanismo simple para recoger propuestas de los integrantes de una comunidad, como un buzón, una asamblea o una consulta, con reglas, plazos y forma de priorizar y devolver resultados.','Plan','4 semanas',26,array['Participación colectiva','Mecanismos']::text[],array['crear']::text[],'ficticios',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion diseno de procesos. facilitacion. equidad en la participacion. redaccion. un editor de diagramas. hoja de calculo. un editor de documentos.',$a13sld${"id": "disenando-una-propuesta-para-fortalecer-la-participacion-colecti", "area": "sociedad", "areas2": ["derecho"], "titulo": "Diseñando una propuesta para fortalecer la participación colectiva con un mecanismo participativo", "resumen": "Diseña un mecanismo simple para recoger propuestas de los integrantes de una comunidad, como un buzón, una asamblea o una consulta, con reglas, plazos y forma de priorizar y devolver resultados.", "tipo": "Plan", "tiempo": "4 semanas", "horas": 26, "etiquetas": ["Participación colectiva", "Mecanismos"], "intencion": ["crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["Muchas comunidades quieren escuchar a sus integrantes, pero no tienen una forma ordenada de hacerlo: las propuestas llegan por mensajes sueltos y las decisiones las toman unos pocos. Eso genera desconfianza y desinterés.", "Un mecanismo claro y justo permite que más voces sean tomadas en cuenta."], "desarrollar": ["Elige un caso, como una junta vecinal, un centro de estudiantes o un grupo de voluntarios, y diseña un mecanismo para recoger propuestas: cómo se presentan, quién las revisa, cómo se priorizan, cómo se decide y cómo se informa el resultado. Dibuja el flujo.", "Pruébalo con diez propuestas ficticias, comprueba si el proceso es entendible y justo y ajusta. Resume el mecanismo en una hoja con pasos y plazos."], "ampliaciones": [{"titulo": "Votación", "aporta": "compara formas de priorizar, como votación, puntos o consenso."}, {"titulo": "Respuesta a quien propone", "aporta": "define cómo se responde a cada propuesta."}, {"titulo": "Participación de personas con menos acceso", "aporta": "adapta el mecanismo para quienes no pueden asistir."}], "objetivos": ["Diseñar un mecanismo de propuestas.", "Definir reglas de priorización.", "Probarlo con casos ficticios.", "Resumirlo."], "habilidades": ["Diseño de procesos.", "Facilitación.", "Equidad en la participación.", "Redacción."], "herramientas": ["Un editor de diagramas.", "Hoja de cálculo.", "Un editor de documentos."], "lineamientos": ["Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "Mantén la neutralidad: el mecanismo no debe favorecer a ningún grupo.", "No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar."], "otroSector": "El mismo mecanismo sirve para recoger sugerencias en una empresa o en una universidad."}$a13sld$::jsonb,23),
('desigualdad-en-el-acceso-a-internet-entre-distintos-grupos-de-pe','sociedad',array['tecnologia']::text[],'Desigualdad en el acceso a internet entre distintos grupos de personas','Analiza con datos públicos quiénes tienen acceso a internet y quiénes no, según zona, edad, nivel de ingresos o tipo de conexión, y qué diferencias de calidad existen incluso entre quienes sí lo tienen.','Análisis','3 a 4 semanas',24,array['Brecha digital','Acceso a internet']::text[],array['investigar']::text[],'publicos',NULL,'trabajo social sociologia ingenieria de sistemas estadistica comunicaciones educacion ingenieria industrial administracion analisis de estadisticas publicas. graficos. pensamiento critico. redaccion. estadisticas oficiales. hoja de calculo. un editor de graficos.',$a14sld${"id": "desigualdad-en-el-acceso-a-internet-entre-distintos-grupos-de-pe", "area": "sociedad", "areas2": ["tecnologia"], "titulo": "Desigualdad en el acceso a internet entre distintos grupos de personas", "resumen": "Analiza con datos públicos quiénes tienen acceso a internet y quiénes no, según zona, edad, nivel de ingresos o tipo de conexión, y qué diferencias de calidad existen incluso entre quienes sí lo tienen.", "tipo": "Análisis", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Brecha digital", "Acceso a internet"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Trabajo Social", "Sociología", "Ingeniería de Sistemas", "Estadística", "Comunicaciones", "Educación", "Ingeniería Industrial", "Administración"], "problema": ["Se dice que todos estamos conectados, pero tener un celular con datos limitados no es lo mismo que tener internet estable en casa. Esa diferencia afecta quién puede estudiar, trabajar o hacer trámites.", "Mostrar las brechas con datos permite hablar con precisión del problema."], "desarrollar": ["Con encuestas oficiales y estadísticas públicas, compara el acceso a internet en zonas urbanas y rurales, por grupos de edad, por nivel socioeconómico y por tipo de dispositivo y conexión. Organiza los datos en tablas y gráficos.", "Describe las brechas principales, distingue entre acceso, calidad y uso y propón tres preguntas que valdría la pena investigar a nivel local."], "ampliaciones": [{"titulo": "Cobertura vs uso", "aporta": "compara dónde hay cobertura y dónde se usa."}, {"titulo": "Costo de la conexión", "aporta": "estima cuánto del ingreso se destina a internet."}, {"titulo": "Mapa de zonas", "aporta": "elabora un mapa de brechas de tu región."}], "objetivos": ["Reunir datos oficiales.", "Comparar grupos.", "Distinguir acceso, calidad y uso.", "Plantear nuevas preguntas."], "habilidades": ["Análisis de estadísticas públicas.", "Gráficos.", "Pensamiento crítico.", "Redacción."], "herramientas": ["Estadísticas oficiales.", "Hoja de cálculo.", "Un editor de gráficos."], "lineamientos": ["Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Cita la fuente y la fecha de cada dato: las cifras cambian cada año.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema."], "otroSector": "El mismo análisis sirve para brechas de acceso a servicios financieros o de salud."}$a14sld$::jsonb,24),
('como-afecta-la-falta-de-acceso-a-internet-a-las-oportunidades-de','sociedad',array['tecnologia','educacion']::text[],'¿Cómo afecta la falta de acceso a internet a las oportunidades de estudio y trabajo?','Investiga cómo la mala conexión o la falta de internet afecta las oportunidades de aprendizaje y de empleo de las personas, con datos públicos y relatos voluntarios y anónimos.','Investigación','3 a 4 semanas',24,array['Conectividad','Oportunidades']::text[],array['investigar']::text[],'propios',NULL,'trabajo social sociologia ingenieria de sistemas estadistica comunicaciones educacion ingenieria industrial administracion diseno de encuestas. analisis de datos. redaccion. propuestas de mejora. un formulario en linea. hoja de calculo. estadisticas oficiales.',$a15sld${"id": "como-afecta-la-falta-de-acceso-a-internet-a-las-oportunidades-de", "area": "sociedad", "areas2": ["tecnologia", "educacion"], "titulo": "¿Cómo afecta la falta de acceso a internet a las oportunidades de estudio y trabajo?", "resumen": "Investiga cómo la mala conexión o la falta de internet afecta las oportunidades de aprendizaje y de empleo de las personas, con datos públicos y relatos voluntarios y anónimos.", "tipo": "Investigación", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Conectividad", "Oportunidades"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Ingeniería de Sistemas", "Estadística", "Comunicaciones", "Educación", "Ingeniería Industrial", "Administración"], "problema": ["Clases virtuales, postulaciones, trámites y cursos dependen de internet. Quien no tiene una conexión estable pierde clases, oportunidades laborales o plazos, aunque tenga capacidad y ganas.", "Documentar esos efectos ayuda a que el problema se entienda como algo más que una incomodidad."], "desarrollar": ["Con una encuesta breve y voluntaria a estudiantes o jóvenes, pregunta qué actividades han dejado de hacer o hicieron con dificultad por la conexión, y cuánto gastan en datos. Complementa con estadísticas públicas.", "Resume los efectos en estudio, trabajo y trámites, estima el impacto en horas perdidas y propón medidas de apoyo, como espacios de conexión comunitarios o materiales descargables."], "ampliaciones": [{"titulo": "Soluciones locales", "aporta": "mapea espacios con conexión gratuita en tu zona."}, {"titulo": "Materiales sin conexión", "aporta": "propón formatos que funcionen sin internet."}, {"titulo": "Costo de datos", "aporta": "calcula cuánto cuesta estar conectado."}], "objetivos": ["Medir el efecto de la conectividad.", "Estimar horas y costos perdidos.", "Presentar relatos anónimos.", "Proponer medidas de apoyo."], "habilidades": ["Diseño de encuestas.", "Análisis de datos.", "Redacción.", "Propuestas de mejora."], "herramientas": ["Un formulario en línea.", "Hoja de cálculo.", "Estadísticas oficiales."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema."], "otroSector": "El mismo estudio sirve para entender el efecto de la conectividad en el trabajo remoto."}$a15sld$::jsonb,25),
('analizando-brechas-de-acceso-a-servicios-basicos','sociedad',array['ciudades']::text[],'Analizando brechas de acceso a servicios básicos','Compara el acceso a agua, saneamiento, electricidad y otros servicios básicos entre distintas zonas o grupos, y describe qué diferencias existen y a quiénes afectan más.','Análisis','3 a 4 semanas',24,array['Servicios básicos','Brechas']::text[],array['investigar']::text[],'publicos',NULL,'trabajo social sociologia ingenieria de sistemas estadistica comunicaciones educacion ingenieria industrial administracion analisis de estadisticas. visualizacion. pensamiento critico. redaccion. estadisticas oficiales. hoja de calculo. un editor de mapas o graficos.',$a16sld${"id": "analizando-brechas-de-acceso-a-servicios-basicos", "area": "sociedad", "areas2": ["ciudades"], "titulo": "Analizando brechas de acceso a servicios básicos", "resumen": "Compara el acceso a agua, saneamiento, electricidad y otros servicios básicos entre distintas zonas o grupos, y describe qué diferencias existen y a quiénes afectan más.", "tipo": "Análisis", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Servicios básicos", "Brechas"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Trabajo Social", "Sociología", "Ingeniería de Sistemas", "Estadística", "Comunicaciones", "Educación", "Ingeniería Industrial", "Administración"], "problema": ["Que un servicio básico exista no significa que llegue a todos de la misma manera. Hay familias sin agua potable continua, sin desagüe o con electricidad inestable, y esas diferencias suelen coincidir con otras desigualdades.", "Analizarlas con datos permite saber dónde están los mayores vacíos."], "desarrollar": ["Con estadísticas oficiales, compara el acceso a los servicios básicos entre departamentos, entre zonas urbanas y rurales o entre grupos según la información disponible. Presenta las diferencias en tablas y mapas simples.", "Describe cuáles son los servicios con mayores brechas, a qué grupos afectan más y qué efectos tiene en la vida diaria, como salud, tiempo o gastos. Propón preguntas para profundizar a nivel local."], "ampliaciones": [{"titulo": "Costo de no tener servicio", "aporta": "estima cuánto cuesta no tener agua o desagüe."}, {"titulo": "Tiempo invertido", "aporta": "calcula el tiempo que lleva conseguir el servicio."}, {"titulo": "Evolución", "aporta": "compara con datos de años anteriores."}], "objetivos": ["Reunir datos de servicios básicos.", "Comparar zonas y grupos.", "Identificar mayores brechas.", "Plantear preguntas locales."], "habilidades": ["Análisis de estadísticas.", "Visualización.", "Pensamiento crítico.", "Redacción."], "herramientas": ["Estadísticas oficiales.", "Hoja de cálculo.", "Un editor de mapas o gráficos."], "lineamientos": ["Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "Presenta datos y no culpables: las brechas tienen causas diversas."], "otroSector": "El mismo análisis sirve para brechas de acceso a salud o educación."}$a16sld$::jsonb,26),
('igualdad-de-oportunidades-en-distintos-contextos-diferencias-den','sociedad',array['educacion']::text[],'Igualdad de oportunidades en distintos contextos: diferencias dentro de una comunidad y entre contextos socioeconómicos','Compara las oportunidades de educación, empleo y servicios entre personas que viven en contextos distintos, usando datos públicos, y distingue qué diferencias dependen del lugar, de los recursos o de las redes.','Análisis','4 semanas',26,array['Igualdad de oportunidades','Contexto socioeconómico']::text[],array['investigar']::text[],'publicos',NULL,'trabajo social sociologia ingenieria de sistemas estadistica comunicaciones educacion ingenieria industrial administracion analisis de estadisticas. pensamiento critico. visualizacion. redaccion. estadisticas oficiales. hoja de calculo. un editor de graficos.',$a17sld${"id": "igualdad-de-oportunidades-en-distintos-contextos-diferencias-den", "area": "sociedad", "areas2": ["educacion"], "titulo": "Igualdad de oportunidades en distintos contextos: diferencias dentro de una comunidad y entre contextos socioeconómicos", "resumen": "Compara las oportunidades de educación, empleo y servicios entre personas que viven en contextos distintos, usando datos públicos, y distingue qué diferencias dependen del lugar, de los recursos o de las redes.", "tipo": "Análisis", "tiempo": "4 semanas", "horas": 26, "etiquetas": ["Igualdad de oportunidades", "Contexto socioeconómico"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Trabajo Social", "Sociología", "Ingeniería de Sistemas", "Estadística", "Comunicaciones", "Educación", "Ingeniería Industrial", "Administración"], "problema": ["Dos personas con el mismo talento pueden tener caminos muy distintos según dónde nacen, qué recursos tienen y qué redes los apoyan. A veces estas diferencias se explican como mérito individual cuando también influyen condiciones de partida.", "Compararlas con datos permite hablar de desigualdad con más precisión."], "desarrollar": ["Con estadísticas oficiales, compara indicadores de educación, ingresos, empleo y acceso a servicios entre zonas o grupos socioeconómicos. Organiza los datos en tablas y gráficos y describe las diferencias más marcadas.", "Distingue entre factores como lugar, recursos e información, y escribe un análisis de dos a tres páginas sobre cómo se manifiestan las diferencias de oportunidad dentro de una misma comunidad, sin generalizar a personas."], "ampliaciones": [{"titulo": "Movilidad", "aporta": "revisa estudios sobre cómo cambian las oportunidades entre generaciones."}, {"titulo": "Redes de apoyo", "aporta": "analiza el papel de contactos e información."}, {"titulo": "Propuestas", "aporta": "plantea medidas que reduzcan diferencias de partida."}], "objetivos": ["Reunir indicadores públicos.", "Comparar contextos.", "Distinguir factores.", "Redactar un análisis."], "habilidades": ["Análisis de estadísticas.", "Pensamiento crítico.", "Visualización.", "Redacción."], "herramientas": ["Estadísticas oficiales.", "Hoja de cálculo.", "Un editor de gráficos."], "lineamientos": ["Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "Evita estereotipos: habla de condiciones y no de características de personas."], "otroSector": "El mismo análisis sirve para comparar oportunidades entre regiones o sectores laborales."}$a17sld$::jsonb,27),
('identificando-barreras-para-acceder-a-recursos-comunitarios','sociedad',array['ciudades']::text[],'Identificando barreras para acceder a recursos comunitarios','Identifica qué dificultades encuentran las personas para usar recursos que existen en su comunidad, como comedores, bibliotecas o centros de salud, y por qué algunos recursos no se aprovechan.','Análisis','3 semanas',22,array['Recursos comunitarios','Acceso']::text[],array['investigar','resolver']::text[],'propios',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion observacion. diseno de encuestas. analisis cualitativo. propuestas de mejora. un formulario en linea. hoja de calculo. una guia de observacion.',$a18sld${"id": "identificando-barreras-para-acceder-a-recursos-comunitarios", "area": "sociedad", "areas2": ["ciudades"], "titulo": "Identificando barreras para acceder a recursos comunitarios", "resumen": "Identifica qué dificultades encuentran las personas para usar recursos que existen en su comunidad, como comedores, bibliotecas o centros de salud, y por qué algunos recursos no se aprovechan.", "tipo": "Análisis", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Recursos comunitarios", "Acceso"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["Hay recursos comunitarios que existen pero no se usan por falta de información, horarios, distancia, desconfianza o requisitos poco claros. Esto se percibe como falta de interés, cuando en realidad son barreras de acceso.", "Identificarlas permite mejorar el servicio y acercarlo a quienes lo necesitan."], "desarrollar": ["Elige tres recursos comunitarios de tu zona y, con una encuesta breve y conversaciones con permiso, pregunta qué conocen, cuáles han usado y qué dificultades encontraron. Observa también la información disponible, como carteles y horarios.", "Clasifica las barreras en información, horarios, ubicación, requisitos y trato, y propón una mejora sencilla para cada recurso. Resume los hallazgos en una ficha por recurso."], "ampliaciones": [{"titulo": "Prueba de usuario", "aporta": "intenta acceder tú a un recurso y registra los pasos."}, {"titulo": "Por grupos", "aporta": "compara barreras entre jóvenes y personas mayores."}, {"titulo": "Lista de verificación", "aporta": "crea una lista para evaluar la accesibilidad de un recurso."}], "objetivos": ["Seleccionar recursos comunitarios.", "Identificar barreras.", "Clasificarlas.", "Proponer mejoras."], "habilidades": ["Observación.", "Diseño de encuestas.", "Análisis cualitativo.", "Propuestas de mejora."], "herramientas": ["Un formulario en línea.", "Hoja de cálculo.", "Una guía de observación."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "Pide permiso al recurso antes de evaluarlo y presenta tus hallazgos con espíritu de mejora."], "otroSector": "El mismo análisis sirve para detectar barreras en el acceso a servicios de una empresa o institución."}$a18sld$::jsonb,28),
('que-factores-generan-desigualdad-en-el-acceso-a-oportunidades-ed','sociedad',array['educacion']::text[],'¿Qué factores generan desigualdad en el acceso a oportunidades educativas entre jóvenes y cómo influye el entorno familiar?','Investiga qué factores, como ingresos, ubicación, conectividad o apoyo familiar, se asocian con diferencias en las oportunidades educativas de los jóvenes, usando fuentes públicas y casos anónimos.','Investigación','4 semanas',26,array['Desigualdad educativa','Entorno familiar']::text[],array['investigar']::text[],'publicos',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion analisis de estadisticas. entrevistas. pensamiento critico. redaccion. estadisticas oficiales. una guia de entrevista. un editor de documentos.',$a19sld${"id": "que-factores-generan-desigualdad-en-el-acceso-a-oportunidades-ed", "area": "sociedad", "areas2": ["educacion"], "titulo": "¿Qué factores generan desigualdad en el acceso a oportunidades educativas entre jóvenes y cómo influye el entorno familiar?", "resumen": "Investiga qué factores, como ingresos, ubicación, conectividad o apoyo familiar, se asocian con diferencias en las oportunidades educativas de los jóvenes, usando fuentes públicas y casos anónimos.", "tipo": "Investigación", "tiempo": "4 semanas", "horas": 26, "etiquetas": ["Desigualdad educativa", "Entorno familiar"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["Entrar y mantenerse en la educación superior no depende solo del esfuerzo: influyen el dinero para materiales, el tiempo, el tipo de colegio, la conectividad y el apoyo de la familia. Estas diferencias suelen ser poco visibles.", "Conocer los factores permite entender mejor las trayectorias y diseñar apoyos."], "desarrollar": ["Reúne estudios y estadísticas oficiales sobre acceso, permanencia y finalización de estudios según nivel socioeconómico, zona y otros factores, y resume los principales hallazgos con sus fuentes.", "Complementa con tres a cinco relatos anónimos y voluntarios de estudiantes sobre qué los ayudó o dificultó. Organiza los factores en un esquema y escribe un informe corto con precaución para no generalizar."], "ampliaciones": [{"titulo": "Becas y apoyos", "aporta": "revisa qué apoyos existen y quiénes los usan."}, {"titulo": "Trayectorias", "aporta": "compara dos trayectorias ficticias."}, {"titulo": "Rol de la familia", "aporta": "analiza distintos tipos de apoyo familiar."}], "objetivos": ["Reunir fuentes oficiales.", "Identificar factores de desigualdad.", "Recoger relatos anónimos.", "Redactar un informe cuidadoso."], "habilidades": ["Análisis de estadísticas.", "Entrevistas.", "Pensamiento crítico.", "Redacción."], "herramientas": ["Estadísticas oficiales.", "Una guía de entrevista.", "Un editor de documentos."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Trata el tema con respeto: usa casos inventados o anónimos, sin datos que identifiquen a nadie, y si alguien necesita ayuda urgente remítelo a los servicios oficiales de atención, sin dar consejos psicológicos ni legales.", "Evita juzgar a las familias: describe contextos y apoyos."], "otroSector": "El mismo análisis sirve para entender desigualdades de acceso a capacitación laboral."}$a19sld$::jsonb,29),
('que-dificultades-enfrentan-las-personas-mayores-para-participar','sociedad',array['tecnologia']::text[],'¿Qué dificultades enfrentan las personas mayores para participar en actividades digitales y sociales?','Descubre qué obstáculos encuentran las personas mayores para usar aplicaciones, hacer trámites en línea o sumarse a actividades sociales, y qué apoyos les ayudarían.','Investigación','3 a 4 semanas',22,array['Personas mayores','Inclusión digital']::text[],array['investigar','resolver']::text[],'propios',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion escucha activa. observacion. diseno de materiales. comunicacion. una guia de conversacion. material impreso. un editor de documentos.',$a20sld${"id": "que-dificultades-enfrentan-las-personas-mayores-para-participar", "area": "sociedad", "areas2": ["tecnologia"], "titulo": "¿Qué dificultades enfrentan las personas mayores para participar en actividades digitales y sociales?", "resumen": "Descubre qué obstáculos encuentran las personas mayores para usar aplicaciones, hacer trámites en línea o sumarse a actividades sociales, y qué apoyos les ayudarían.", "tipo": "Investigación", "tiempo": "3 a 4 semanas", "horas": 22, "etiquetas": ["Personas mayores", "Inclusión digital"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["Muchos trámites, comunicaciones y actividades se han mudado a lo digital, y las personas mayores pueden quedar fuera por falta de práctica, miedo a equivocarse o dispositivos poco adecuados. A veces también por trato impaciente.", "Entender sus dificultades permite diseñar apoyos útiles y respetuosos."], "desarrollar": ["Conversa, con permiso y en un ambiente cómodo, con cinco a diez personas mayores sobre qué actividades digitales realizan, cuáles les cuestan y por qué. Observa con su permiso cómo usan una aplicación común.", "Agrupa las dificultades, como letra pequeña, miedo, falta de ayuda o costos, y propón apoyos concretos: una guía ilustrada, un taller breve o un acompañamiento entre vecinos. Pruébalo en pequeño."], "ampliaciones": [{"titulo": "Guía ilustrada", "aporta": "crea una guía paso a paso con letra grande."}, {"titulo": "Taller intergeneracional", "aporta": "diseña un taller donde jóvenes enseñan y aprenden."}, {"titulo": "Seguridad", "aporta": "agrega recomendaciones para evitar estafas."}], "objetivos": ["Conversar con respeto.", "Identificar dificultades.", "Proponer apoyos.", "Probarlos."], "habilidades": ["Escucha activa.", "Observación.", "Diseño de materiales.", "Comunicación."], "herramientas": ["Una guía de conversación.", "Material impreso.", "Un editor de documentos."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "No tomes fotos ni grabes sin permiso y trata a las personas con respeto y paciencia."], "otroSector": "El mismo trabajo sirve para diseñar servicios en línea accesibles para clientes mayores."}$a20sld$::jsonb,30),
('que-barreras-encuentran-las-personas-con-discapacidad-para-parti','sociedad',array['salud']::text[],'¿Qué barreras encuentran las personas con discapacidad para participar en actividades sociales?','Analiza qué barreras físicas, de información y de actitud pueden encontrar las personas con discapacidad al participar en actividades sociales, usando fuentes públicas y el enfoque de derechos.','Análisis','3 a 4 semanas',24,array['Discapacidad','Participación social']::text[],array['investigar']::text[],'publicos',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion analisis de accesibilidad. lectura de fuentes. empatia. redaccion. fuentes oficiales. una lista de verificacion. un editor de documentos.',$a21sld${"id": "que-barreras-encuentran-las-personas-con-discapacidad-para-parti", "area": "sociedad", "areas2": ["salud"], "titulo": "¿Qué barreras encuentran las personas con discapacidad para participar en actividades sociales?", "resumen": "Analiza qué barreras físicas, de información y de actitud pueden encontrar las personas con discapacidad al participar en actividades sociales, usando fuentes públicas y el enfoque de derechos.", "tipo": "Análisis", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Discapacidad", "Participación social"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["Participar en un evento, un grupo o un taller no depende solo de querer: también de si el lugar es accesible, de si la información se puede entender y de cómo se trata a las personas. Esas barreras suelen ser invisibles para quienes no las viven.", "Reconocerlas es el primer paso para organizar actividades más inclusivas."], "desarrollar": ["Con fuentes oficiales y materiales de organizaciones de personas con discapacidad, reúne los tipos de barreras que se describen, como físicas, comunicacionales y actitudinales, y arma una lista con ejemplos de actividades comunitarias.", "Revisa, con permiso, un espacio o una convocatoria de tu entorno con esa lista, señala qué barreras podría haber y propón mejoras sencillas. Presenta los hallazgos con enfoque de derechos y no de lástima."], "ampliaciones": [{"titulo": "Lista de verificación", "aporta": "crea una lista para organizar eventos accesibles."}, {"titulo": "Lenguaje respetuoso", "aporta": "elabora una guía de términos adecuados."}, {"titulo": "Participación de las propias personas", "aporta": "propón cómo incluir su voz en el diseño."}], "objetivos": ["Identificar tipos de barreras.", "Aplicarlas a una actividad.", "Proponer mejoras.", "Comunicar con enfoque de derechos."], "habilidades": ["Análisis de accesibilidad.", "Lectura de fuentes.", "Empatía.", "Redacción."], "herramientas": ["Fuentes oficiales.", "Una lista de verificación.", "Un editor de documentos."], "lineamientos": ["Trata el tema con respeto: usa casos inventados o anónimos, sin datos que identifiquen a nadie, y si alguien necesita ayuda urgente remítelo a los servicios oficiales de atención, sin dar consejos psicológicos ni legales.", "Incluye la voz de personas con discapacidad en tu proceso cuando sea posible y evita hablar por ellas.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión."], "otroSector": "La misma lista sirve para evaluar la accesibilidad de un servicio o producto digital."}$a21sld$::jsonb,31),
('convivencia-y-trabajo-en-equipo-en-grupos-diversos-y-como-foment','sociedad',array['educacion']::text[],'Convivencia y trabajo en equipo en grupos diversos, y cómo fomentar el respeto entre personas con costumbres diferentes','Reúne ejemplos de cómo se logra convivir y trabajar bien en grupos con personas de distintas costumbres, y elabora una guía de buenas prácticas para equipos y comunidades diversas.','Guía','3 a 4 semanas',24,array['Convivencia','Diversidad']::text[],array['investigar','crear']::text[],'propios',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion escucha activa. analisis cualitativo. comunicacion intercultural. redaccion. una guia de conversacion. un editor de documentos. fuentes sobre interculturalidad.',$a22sld${"id": "convivencia-y-trabajo-en-equipo-en-grupos-diversos-y-como-foment", "area": "sociedad", "areas2": ["educacion"], "titulo": "Convivencia y trabajo en equipo en grupos diversos, y cómo fomentar el respeto entre personas con costumbres diferentes", "resumen": "Reúne ejemplos de cómo se logra convivir y trabajar bien en grupos con personas de distintas costumbres, y elabora una guía de buenas prácticas para equipos y comunidades diversas.", "tipo": "Guía", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Convivencia", "Diversidad"], "intencion": ["investigar", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["En la universidad y en la comunidad se juntan personas con costumbres, ritmos y formas de comunicarse distintas. Eso enriquece, pero también puede generar malentendidos que se interpretan como falta de respeto.", "Aprender a leer esas diferencias facilita la convivencia."], "desarrollar": ["Conversa de manera anónima y voluntaria con personas de distintos orígenes sobre situaciones de malentendido que han vivido y qué ayudó a resolverlas. Complementa con lecturas sobre interculturalidad.", "Agrupa las situaciones en categorías, como saludos, puntualidad, comunicación o tiempos, y elabora una guía de diez prácticas para equipos diversos con ejemplos y preguntas para conversar."], "ampliaciones": [{"titulo": "Acuerdos de equipo", "aporta": "diseña un taller para armar acuerdos de convivencia."}, {"titulo": "Mitos y estereotipos", "aporta": "analiza ideas erradas sobre otras costumbres."}, {"titulo": "Versión ilustrada", "aporta": "convierte la guía en un material visual."}], "objetivos": ["Recoger experiencias.", "Agrupar situaciones.", "Elaborar prácticas.", "Redactar una guía."], "habilidades": ["Escucha activa.", "Análisis cualitativo.", "Comunicación intercultural.", "Redacción."], "herramientas": ["Una guía de conversación.", "Un editor de documentos.", "Fuentes sobre interculturalidad."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Evita generalizar sobre grupos y presenta ejemplos como situaciones y no como rasgos de una cultura.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema."], "otroSector": "La misma guía sirve para equipos de trabajo con integrantes de varias regiones o países."}$a22sld$::jsonb,32),
('que-factores-favorecen-una-buena-convivencia','sociedad',array[]::text[],'¿Qué factores favorecen una buena convivencia?','Identifica qué condiciones hacen que un grupo, un salón o una comunidad conviva bien, como reglas claras, comunicación, tiempo compartido y confianza, comparando grupos que lo logran y otros que no.','Investigación','3 semanas',20,array['Convivencia','Factores']::text[],array['investigar']::text[],'propios',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion observacion. analisis cualitativo. sintesis. diseno de instrumentos. un formulario en linea. una guia de observacion. un editor de documentos.',$a23sld${"id": "que-factores-favorecen-una-buena-convivencia", "area": "sociedad", "areas2": [], "titulo": "¿Qué factores favorecen una buena convivencia?", "resumen": "Identifica qué condiciones hacen que un grupo, un salón o una comunidad conviva bien, como reglas claras, comunicación, tiempo compartido y confianza, comparando grupos que lo logran y otros que no.", "tipo": "Investigación", "tiempo": "3 semanas", "horas": 20, "etiquetas": ["Convivencia", "Factores"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["Algunos grupos conviven con armonía y otros con tensiones constantes, aunque las personas sean parecidas. La diferencia suele estar en prácticas y condiciones que pueden observarse.", "Identificarlas permite fomentarlas en otros grupos."], "desarrollar": ["Elige dos o tres grupos con permiso, como un salón, un club o una junta vecinal, y con una encuesta breve y observación respetuosa identifica qué prácticas tienen en común los que conviven mejor: reuniones, reglas, canales de comunicación y resolución de problemas.", "Organiza los factores en un esquema y redacta una lista de diez condiciones que favorecen la convivencia, con ejemplos concretos y preguntas de autoevaluación para un grupo."], "ampliaciones": [{"titulo": "Termómetro de convivencia", "aporta": "diseña una encuesta corta para medir el clima de un grupo."}, {"titulo": "Rituales", "aporta": "analiza el papel de actividades compartidas."}, {"titulo": "Cambios en el tiempo", "aporta": "observa cómo cambia un grupo a lo largo del ciclo."}], "objetivos": ["Observar grupos.", "Identificar condiciones de buena convivencia.", "Elaborar una lista.", "Diseñar autoevaluación."], "habilidades": ["Observación.", "Análisis cualitativo.", "Síntesis.", "Diseño de instrumentos."], "herramientas": ["Un formulario en línea.", "Una guía de observación.", "Un editor de documentos."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir."], "otroSector": "El mismo estudio sirve para entender el clima de un equipo de trabajo."}$a23sld$::jsonb,33),
('estrategias-para-resolver-conflictos-en-grupos-y-por-que-surgen','sociedad',array['educacion']::text[],'Estrategias para resolver conflictos en grupos y por qué surgen en los grupos de estudio','Analiza por qué surgen conflictos en grupos, en especial de estudio, y diseña una guía de estrategias para prevenirlos y resolverlos con respeto, con casos ficticios y práctica.','Guía','3 a 4 semanas',24,array['Conflictos','Grupos de estudio']::text[],array['investigar','crear']::text[],'ficticios',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion resolucion de conflictos. comunicacion asertiva. analisis de casos. redaccion. casos ficticios. un editor de documentos. companeros para practicar.',$a24sld${"id": "estrategias-para-resolver-conflictos-en-grupos-y-por-que-surgen", "area": "sociedad", "areas2": ["educacion"], "titulo": "Estrategias para resolver conflictos en grupos y por qué surgen en los grupos de estudio", "resumen": "Analiza por qué surgen conflictos en grupos, en especial de estudio, y diseña una guía de estrategias para prevenirlos y resolverlos con respeto, con casos ficticios y práctica.", "tipo": "Guía", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Conflictos", "Grupos de estudio"], "intencion": ["investigar", "crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["Un trabajo grupal puede volverse un problema si alguien siente que carga con todo, si hay malentendidos o si los acuerdos son poco claros. Muchas veces el conflicto se acumula en silencio y explota cerca de la entrega.", "Conocer sus causas y tener estrategias a mano ayuda a resolver a tiempo."], "desarrollar": ["Redacta cinco casos ficticios de conflicto en grupos, como reparto desigual, impuntualidad o diferencias de criterio, y analiza las causas. Con fuentes sobre manejo de conflictos, reúne cinco estrategias, como escuchar, acordar reglas y buscar mediador.", "Elabora una guía con preguntas y frases para cada situación y practica con compañeros una dramatización de dos de los casos. Ajusta según lo que aprendan."], "ampliaciones": [{"titulo": "Acuerdos al inicio", "aporta": "diseña un formato para acordar reglas al comenzar un trabajo."}, {"titulo": "Señales tempranas", "aporta": "lista señales de que un conflicto se avecina."}, {"titulo": "Cuándo pedir ayuda", "aporta": "define cuándo recurrir a un docente o mediador."}], "objetivos": ["Analizar causas de conflicto.", "Reunir estrategias.", "Practicar con casos.", "Redactar una guía."], "habilidades": ["Resolución de conflictos.", "Comunicación asertiva.", "Análisis de casos.", "Redacción."], "herramientas": ["Casos ficticios.", "Un editor de documentos.", "Compañeros para practicar."], "lineamientos": ["Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "Usa casos ficticios y no escribas sobre conflictos reales de personas identificables.", "Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir."], "otroSector": "La misma guía sirve para prevenir conflictos en equipos de proyectos o de trabajo."}$a24sld$::jsonb,34)
